CREATE OR REPLACE FUNCTION public.is_active_workspace_member(_ws uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=_uid AND m.removed_at IS NULL AND w.status='active' AND p.status='active' AND p.deleted_at IS NULL) $$;
CREATE OR REPLACE FUNCTION public.workspace_role_of(_ws uuid,_uid uuid) RETURNS public.workspace_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.role FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=_uid AND m.removed_at IS NULL AND p.status='active' AND p.deleted_at IS NULL $$;
CREATE OR REPLACE FUNCTION public.network_source_access(_id uuid,_manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.trip_distributions d WHERE d.id=_id AND ((public.admin_can('requests',CASE WHEN _manage THEN 'manage' ELSE 'read' END) AND public.admin_can_account(d.source_workspace_id)) OR public.network_workspace_access(d.source_workspace_id,_manage) OR (NOT _manage AND d.original_person_id=auth.uid() AND EXISTS(SELECT 1 FROM public.user_profiles p WHERE p.user_id=auth.uid() AND p.status='active' AND p.deleted_at IS NULL)))) $$;
CREATE OR REPLACE FUNCTION public.guard_distribution_source_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.ride_requests; t public.trips; expected_ws uuid; BEGIN IF TG_OP='UPDATE' AND NEW.selected_workspace_id IS NOT DISTINCT FROM OLD.selected_workspace_id THEN RETURN NEW; END IF; IF TG_OP='UPDATE' AND OLD.selected_workspace_id IS NOT NULL THEN RAISE EXCEPTION 'Provider selection is immutable'; END IF; IF NEW.trip_id IS NOT NULL THEN SELECT * INTO t FROM public.trips WHERE id=NEW.trip_id FOR UPDATE; IF NOT FOUND OR t.trip_kind<>'passenger' OR t.status IN ('canceled','cancelled','completed','declined','unavailable','no_show') OR EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=t.created_by AND is_test_account) THEN RAISE EXCEPTION 'Source trip unavailable'; END IF; IF TG_OP='INSERT' AND t.network_provider_workspace_id IS NOT NULL THEN RAISE EXCEPTION 'Trip already reserved'; END IF; IF NEW.request_id IS NULL AND t.ride_request_id IS NOT NULL THEN NEW.request_id:=t.ride_request_id; END IF; END IF; IF NEW.request_id IS NOT NULL THEN SELECT * INTO r FROM public.ride_requests WHERE id=NEW.request_id FOR UPDATE; IF NOT FOUND OR r.is_test OR r.trip_kind<>'passenger' OR r.status IN ('canceled','cancelled','completed','declined','unavailable','no_show') THEN RAISE EXCEPTION 'Source request unavailable'; END IF; IF r.workspace_id IS DISTINCT FROM NEW.source_workspace_id THEN RAISE EXCEPTION 'Source ownership mismatch'; END IF; ELSIF NEW.trip_id IS NOT NULL THEN SELECT CASE WHEN count(*)=1 THEN min(m.workspace_id::text)::uuid END INTO expected_ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.user_id=t.created_by AND m.removed_at IS NULL AND w.status='active' AND p.status='active'; IF expected_ws IS NULL OR expected_ws IS DISTINCT FROM NEW.source_workspace_id THEN RAISE EXCEPTION 'Verified source ownership required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_distribution_source_state BEFORE INSERT OR UPDATE OF selected_workspace_id ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.guard_distribution_source_state();
CREATE OR REPLACE FUNCTION public.guard_network_schedule_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.network_provider_workspace_id IS NOT NULL AND (NEW.driver_id IS DISTINCT FROM OLD.driver_id OR NEW.scheduled_start_time IS DISTINCT FROM OLD.scheduled_start_time) THEN IF NEW.network_status<>'reserved' OR NEW.status IN ('completed','canceled','cancelled','no_show') OR NOT EXISTS(SELECT 1 FROM public.trip_distributions WHERE id=NEW.network_distribution_id AND selected_workspace_id=NEW.network_provider_workspace_id AND status='provider_selected') THEN RAISE EXCEPTION 'Reservation is no longer active'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_network_schedule_state BEFORE UPDATE OF driver_id,scheduled_start_time ON public.trips FOR EACH ROW EXECUTE FUNCTION public.guard_network_schedule_state();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='network_list_activity'; def:=replace(def,'d.id,d.mfn_id,d.source_mfn_id','d.id,d.request_id,d.trip_id,d.mfn_id,d.source_mfn_id'); EXECUTE def; SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='network_accept_offer'; def:=replace(def,'IF NOT FOUND THEN PERFORM set_config(''app.network_write'',previous_flag,true); RETURN jsonb_build_object(''ok'',false,''error'',''This offer is no longer available''); END IF;','IF NOT FOUND THEN RAISE EXCEPTION ''Source trip no longer available''; END IF;'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.suppress_account_message_notifications() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.related_person_id IS NOT NULL THEN RETURN NEW; END IF; RETURN NEW; END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='notify_thread_participants_on_message'; def:=replace(def,'BEGIN','BEGIN IF EXISTS(SELECT 1 FROM public.message_threads WHERE id=NEW.thread_id AND related_person_id IS NOT NULL) THEN RETURN NEW; END IF;'); EXECUTE def; END $$;
COMMENT ON COLUMN public.user_profiles.deleted_at IS 'Login removal tombstone; immutable MFN identity and protected history are retained.';
COMMENT ON COLUMN public.workspace_members.removed_at IS 'Inactive membership retained for attribution; access requires active profile and no removal tombstone.';